import logo from './logo.svg';
import './App.css';
import Categories from './Pages/Categories';

function App() {
  return (
    <div className="App">
      <Categories/>
      <BrowserRouter>
      <Routes>
        <Route path="/" element={<Register />} />
        <Route path="/verify-otp" element={<OtpVerify />} />
        <Route path="/add-user" element={<AddUser />} />
      </Routes>
    </BrowserRouter>
    </div>
  );
}

export default App;
